      await importNativeSdkArchiveOriginals({
        projectRoot: root,
        run: await runtime.inspect(run.runId),
        ref: backupRef,
      });
      await fs.writeFile(
        backupRef,
        JSON.stringify({ ...parsedBackup, files: [...parsedBackup.files].reverse() }),
      );
      await importNativeSdkArchiveOriginals({
        projectRoot: root,
        run: await runtime.inspect(run.runId),
