          })),
        }),
      );
      await expect(
        importNativeSdkArchiveOriginals({
          projectRoot: root,
          run: await runtime.inspect(run.runId),
          ref: backupRef,
        }),
      ).rejects.toThrow();
      await fs.writeFile(backupRef, validBackup);
      expect(
        (
          await runNativeCli([
            'archive',
            run.runId,
            '--project-root',
