          },
        },
      });
      await expect(fs.stat(transactionFile)).rejects.toMatchObject({ code: 'ENOENT' });
    } finally {
      try {
        git(['worktree', 'remove', '--force', prepared.projectRoot]);
      } catch {
        // Preserve the assertion failure if setup did not finish cleanly.
      }
    }
  });

