      }),
    ).rejects.toThrow(/OUTCOME_REJECTED/);
    expect((await runtime.inspect(run.runId)).state).toMatchObject({ phase: 'open' });
    await fs.writeFile(path.join(changeDir, 'tasks.md'), '- [x] Build\n');
    run = await runtime.recordOutcome({
