import { spawnSync } from 'child_process';
import { existsSync, promises as fs } from 'fs';
import os from 'os';
import path from 'path';
import { afterEach, describe, expect, it } from 'vitest';
import { runClassicCli } from '../../../domains/comet-classic/classic-cli.js';
import { resolveClassicRunDirectory } from '../../../domains/comet-classic/classic-runtime-paths.js';
import { readRunState, writeRunState } from '../../../domains/engine/state.js';

const scriptsDir = path.resolve('assets', 'skills', 'comet', 'scripts');
const scriptByCommand: Record<string, string> = {
  guard: path.join(scriptsDir, 'comet-guard.mjs'),
  handoff: path.join(scriptsDir, 'comet-handoff.mjs'),
  state: path.join(scriptsDir, 'comet-state.mjs'),
};
const temporary: string[] = [];

afterEach(async () => {
  await Promise.all(
    temporary
      .splice(0)
      .map((dir) => fs.rm(dir, { recursive: true, force: true, maxRetries: 5, retryDelay: 100 })),
  );
});

function run(cwd: string, ...args: string[]) {
  const [command, ...rest] = args;
  return spawnSync(process.execPath, [scriptByCommand[command as string], ...rest], {
    cwd,
    encoding: 'utf8',
  });
}

async function makeProject(): Promise<string> {
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'classic-handoff-'));
  temporary.push(dir);
  await fs.mkdir(path.join(dir, '.comet'), { recursive: true });
  await fs.writeFile(
    path.join(dir, '.comet', 'config.yaml'),
    [
      'schema: comet.project.v1',
      'default_workflow: classic',
      'workflows: [classic]',
      'classic:',
      '  artifact_layout: legacy',
      '',
    ].join('\n'),
  );
  await fs.mkdir(path.join(dir, 'openspec', 'changes'), { recursive: true });
  return dir;
}

async function seedDesignChange(dir: string, name = 'demo'): Promise<string> {
  run(dir, 'state', 'init', name, 'full', '--runtime', 'compat');
  const changeDir = path.join(dir, 'openspec', 'changes', name);
  // Open→design transition requires the open artifacts to exist first.
  await fs.writeFile(path.join(changeDir, 'proposal.md'), 'proposal\n');
  await fs.writeFile(path.join(changeDir, 'design.md'), 'design\n');
  await fs.writeFile(path.join(changeDir, 'tasks.md'), '- [x] implement handoff\n');
  run(dir, 'state', 'transition', name, 'open-complete'); // open -> design (full workflow)
  return changeDir;
}

describe('Classic handoff command', () => {
  it('rejects a nested handoff junction without writing outside the project', async () => {
    const dir = await makeProject();
    const previous = process.cwd();
    process.chdir(dir);
    try {
      expect(
        (await runClassicCli(['state', 'init', 'linked-handoff', 'full', '--runtime', 'compat']))
          .exitCode,
      ).toBe(0);
      const changeDir = path.join(dir, 'openspec', 'changes', 'linked-handoff');
      await fs.writeFile(path.join(changeDir, 'proposal.md'), 'proposal\n');
      await fs.writeFile(path.join(changeDir, 'design.md'), 'design\n');
      await fs.writeFile(path.join(changeDir, 'tasks.md'), '- [x] implement\n');
      expect(
        (await runClassicCli(['state', 'transition', 'linked-handoff', 'open-complete'])).exitCode,
      ).toBe(0);

      const outside = await fs.mkdtemp(path.join(os.tmpdir(), 'classic-handoff-outside-'));
      temporary.push(outside);
      await fs.writeFile(path.join(outside, 'marker.txt'), 'unchanged\n');
      await fs.symlink(
        outside,
        path.join(changeDir, '.comet', 'handoff'),
        process.platform === 'win32' ? 'junction' : 'dir',
      );

      const result = await runClassicCli([
        'handoff',
        'linked-handoff',
        'design',
        '--write',
        '--full',
      ]);

      expect(result.exitCode).not.toBe(0);
      expect(result.stderr).toMatch(/symbolic link or junction/iu);
      expect(await fs.readFile(path.join(outside, 'marker.txt'), 'utf8')).toBe('unchanged\n');
      expect(await fs.readdir(outside)).toEqual(['marker.txt']);
    } finally {
      process.chdir(previous);
    }
  });

  it('references original requirements without generating a default handoff copy', async () => {
    const dir = await makeProject();
    const changeDir = await seedDesignChange(dir);
    const result = run(dir, 'handoff', 'demo', 'design', '--write');
    expect(result.status, result.stderr).toBe(0);
    expect(result.stderr).toContain('[HANDOFF] source openspec/changes/demo/proposal.md');
    expect(existsSync(path.join(changeDir, '.comet/handoff'))).toBe(false);
    expect(run(dir, 'state', 'get', 'demo', 'handoff_context').stdout.trim()).toBe(
      'openspec/changes/demo/proposal.md',
    );
    expect(run(dir, 'state', 'get', 'demo', 'handoff_hash').stdout.trim()).toBe('null');
    const state = await readRunState(await resolveClassicRunDirectory(changeDir));
    expect(state).toMatchObject({
      currentStep: 'full.design.document',
      iteration: 1,
      pending: null,
    });
    expect(
      await fs.readFile(
        path.join(await resolveClassicRunDirectory(changeDir), state!.contextRef),
        'utf8',
      ),
    ).toBe(await fs.readFile(path.join(changeDir, 'proposal.md'), 'utf8'));
    await expect(
      fs.access(path.join(await resolveClassicRunDirectory(changeDir), state!.pendingRef)),
    ).rejects.toMatchObject({ code: 'ENOENT' });
  });

  it('generates one complete optional handoff view without advancing the original Run', async () => {
    const dir = await makeProject();
    const changeDir = await seedDesignChange(dir);
    expect(run(dir, 'handoff', 'demo', 'design', '--write').status).toBe(0);
    const before = await readRunState(await resolveClassicRunDirectory(changeDir));
    const spec = path.join(changeDir, 'specs', 'nested', 'worker', 'spec.md');
    await fs.mkdir(path.dirname(spec), { recursive: true });
    await fs.writeFile(spec, 'The complete nested worker requirement.\n');
    const result = run(dir, 'handoff', 'demo', 'design', '--write', '--full');
    expect(result.status, result.stderr).toBe(0);
    expect(await fs.readdir(path.join(changeDir, '.comet/handoff'))).toEqual(['design-context.md']);
    const view = await fs.readFile(
      path.join(changeDir, '.comet/handoff/design-context.md'),
      'utf8',
    );
    expect(view).toContain('The complete nested worker requirement.');
    expect(view).toContain('openspec/changes/demo/specs/nested/worker/spec.md');
    expect(view).not.toContain('sha256');
    expect(await readRunState(await resolveClassicRunDirectory(changeDir))).toEqual(before);
  });

  it('refreshes the design handoff from the build phase after a Spec Patch', async () => {
    const dir = await makeProject();
    const changeDir = await seedDesignChange(dir);
    expect(run(dir, 'handoff', 'demo', 'design', '--write').status).toBe(0);
    const beforeContext = run(dir, 'state', 'get', 'demo', 'handoff_context').stdout.trim();
    const beforeText = await fs.readFile(path.join(dir, beforeContext), 'utf8');

    // Enter build through the real guard transition, not a forced phase write.
    // The full workflow requires a recorded Design Doc before leaving design.
    const designDoc = path.join(dir, 'docs', 'superpowers', 'specs', 'demo-design.md');
    await fs.mkdir(path.dirname(designDoc), { recursive: true });
    await fs.writeFile(
      designDoc,
      [
        '---',
        'comet_change: demo',
        'role: technical-design',
        'canonical_spec: openspec',
        '---',
        '',
        '# Design',
        '',
      ].join('\n'),
    );
    expect(
      run(dir, 'state', 'set', 'demo', 'design_doc', 'docs/superpowers/specs/demo-design.md')
        .status,
    ).toBe(0);
    const guard = run(dir, 'guard', 'demo', 'design', '--apply');
    expect(guard.status, guard.stderr).toBe(0);
    expect(run(dir, 'state', 'get', 'demo', 'phase').stdout.trim()).toBe('build');
    const runStateBefore = await readRunState(await resolveClassicRunDirectory(changeDir));
    expect(runStateBefore).not.toBeNull();
    expect(runStateBefore!.currentStep).toBe('full.build.configure');

    // Spec Patch the source evidence while in build.
    await fs.appendFile(path.join(changeDir, 'proposal.md'), 'build-phase change\n');

    const result = run(dir, 'handoff', 'demo', 'design', '--write');
    expect(result.status, result.stderr).toBe(0);
    const afterContext = run(dir, 'state', 'get', 'demo', 'handoff_context').stdout.trim();
    expect(await fs.readFile(path.join(dir, afterContext), 'utf8')).toContain('build-phase change');
    expect(await fs.readFile(path.join(dir, afterContext), 'utf8')).not.toBe(beforeText);
    expect(run(dir, 'state', 'get', 'demo', 'handoff_hash').stdout.trim()).toBe('null');

    // The refresh must not move the workflow phase or the Runtime currentStep.
    expect(run(dir, 'state', 'get', 'demo', 'phase').stdout.trim()).toBe('build');
    const runStateAfter = await readRunState(await resolveClassicRunDirectory(changeDir));
    expect(runStateAfter).not.toBeNull();
    expect(runStateAfter!.currentStep).toBe('full.build.configure');
  });

  it('reconciles a matching pending handoff and records recovery once', async () => {
    const dir = await makeProject();
    const changeDir = await seedDesignChange(dir);
    expect(run(dir, 'handoff', 'demo', 'design', '--write').status).toBe(0);
    const hash = run(dir, 'state', 'get', 'demo', 'handoff_hash').stdout.trim();
    const runStateBefore = await readRunState(await resolveClassicRunDirectory(changeDir));
    expect(runStateBefore).not.toBeNull();
    const actionId = `classic-handoff:${hash}`;
    await fs.writeFile(
      path.join(await resolveClassicRunDirectory(changeDir), runStateBefore!.pendingRef),
      JSON.stringify({
        id: actionId,
        stepId: runStateBefore!.currentStep,
        type: 'handoff',
        ref: hash,
      }),
    );
    await writeRunState(await resolveClassicRunDirectory(changeDir), {
      ...runStateBefore!,
      pending: actionId,
    });

    const result = run(dir, 'handoff', 'demo', 'design', '--write');
    expect(result.status).toBe(0);
    const afterRunState = await readRunState(await resolveClassicRunDirectory(changeDir));
    expect(afterRunState).not.toBeNull();
    expect(afterRunState!.pending).toBeNull();
    expect(run(dir, 'handoff', 'demo', 'design', '--write').status).toBe(0);
    const trajectory = (
      await fs.readFile(
        path.join(await resolveClassicRunDirectory(changeDir), afterRunState!.trajectoryRef),
        'utf8',
      )
    )
      .trim()
      .split(/\r?\n/u)
      .map((line) => JSON.parse(line) as { type: string; data?: { kind?: string } });
    expect(
      trajectory.filter(
        (event) => event.type === 'recovery_reconciled' && event.data?.kind === 'classic-handoff',
      ),
    ).toHaveLength(1);
  });
});

import { execFileSync } from 'node:child_process';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, expect, it } from 'vitest';
import { readCheckPolicy } from '../../../domains/comet-classic/classic-check-policy.js';
import { runClassicCli } from '../../../domains/comet-classic/classic-cli.js';
import { prepareClassicLegacyProject } from '../../helpers/classic-project.js';

let root: string;
const identity = { argv: [process.execPath, 'check.cjs'], cwd: '.' };
beforeEach(async () => {
  root = await fs.mkdtemp(path.join(os.tmpdir(), 'classic-check-defaults-'));
  await prepareClassicLegacyProject(root);
  execFileSync('git', ['init', '-b', 'main'], { cwd: root, stdio: 'ignore' });
});
afterEach(async () => {
  await fs.rm(root, { recursive: true, force: true, maxRetries: 5 });
});
async function put(ref: string, text: string) {
  await fs.mkdir(path.dirname(path.join(root, ref)), { recursive: true });
  await fs.writeFile(path.join(root, ref), text);
}
async function invoke(...args: string[]) {
  const separator = args.indexOf('--');
  args.splice(separator < 0 ? args.length : separator, 0, '--json');
  const result = await runClassicCli(args, undefined, { invocationCwd: root });
  return { ...result, response: JSON.parse(result.stdout ?? '{}') };
}
async function cli(...args: string[]) {
  const result = await invoke(...args);
  expect(result.exitCode, result.stdout ?? result.stderr).toBe(0);
  return result.response.data;
}
async function prepare(runtime: 'compat' | 'sdk') {
  await cli('state', 'init', 'demo', 'tweak', '--runtime', runtime, '--isolation', 'current');
  await put('openspec/changes/demo/proposal.md', '# Proposal\nFix source.\n');
  await put('openspec/changes/demo/design.md', '# Design\nKeep public behavior.\n');
  await put('openspec/changes/demo/tasks.md', '- [x] Fix source <!-- comet-task:source -->\n');
  const open = await cli('guard', 'demo', 'open');
  await cli(
    'guard',
    'demo',
    'open',
    '--apply',
    ...(runtime === 'sdk' ? ['--approval-hash', open.approvalHash] : []),
  );
  if (runtime === 'sdk') await cli('state', 'complete-build', 'demo');
}
const policy = (command: Record<string, unknown>) =>
  put(
    '.comet/check-policy.json',
    JSON.stringify({ version: 2, commands: [{ ...identity, ...command }] }),
  );

it.each(['compat', 'sdk'] as const)(
  'applies project timeout to the public %s check run',
  async (runtime) => {
    await prepare(runtime);
    await fs.appendFile(path.join(root, '.comet/config.yaml'), '  check_timeout_ms: 25\n');
    const result = await invoke(
      'check',
      'run',
      'demo',
      'build',
      '--',
      process.execPath,
      '-e',
      // 保持命令存活到超时终止，避免它在 Windows taskkill 枚举期间自然退出。
      'setTimeout(() => {}, 20000)',
    );
    expect(result.exitCode, result.stdout).toBe(124);
    expect(result.response.data.timeoutMs).toBe(25);
  },
);

it.each(['compat', 'sdk'] as const)(
  'lets explicit CLI timeout override the project default for %s',
  async (runtime) => {
    await prepare(runtime);
    await fs.appendFile(path.join(root, '.comet/config.yaml'), '  check_timeout_ms: 1\n');
    const result = await invoke(
      'check',
      'run',
      'demo',
      'build',
      '--timeout-ms',
      '5000',
      '--',
      process.execPath,
      '-e',
      'setTimeout(() => {}, 50)',
    );
    expect(result.exitCode, result.stdout).toBe(0);
    expect(result.response.data.timeoutMs).toBe(5000);
  },
);

it.each([{ presets: ['unknown'] }, { presets: 'vite' }, { presets: [false] }])(
  'rejects invalid presets %j',
  async ({ presets }) => {
    await policy({ presets });
    await expect(readCheckPolicy(root, identity)).rejects.toThrow(/preset/iu);
  },
);

it('does not reuse a command executed under a different explicit timeout', async () => {
  await prepare('compat');
  const argv = [process.execPath, '-e', 'setTimeout(() => {}, 50)'];
  const first = await cli(
    'check',
    'run',
    'demo',
    'build',
    '--local',
    '--timeout-ms',
    '5000',
    '--',
    ...argv,
  );
  expect(first.exitCode).toBe(0);
  const second = await invoke(
    'check',
    'run',
    'demo',
    'build',
    '--local',
    '--timeout-ms',
    '1',
    '--',
    ...argv,
  );
  expect(second.exitCode, second.stdout).toBe(124);
  expect(second.response.data.timeoutMs).toBe(1);
  expect(second.response.data.reused).not.toBe(true);
});

it('rerun preserves the previous resolved timeout rather than a changed project default', async () => {
  await prepare('compat');
  const configPath = path.join(root, '.comet/config.yaml');
  const initialConfig = await fs.readFile(configPath, 'utf8');
  await fs.writeFile(configPath, initialConfig + '  check_timeout_ms: 5000\n');
  const first = await cli(
    'check',
    'run',
    'demo',
    'build',
    '--',
    process.execPath,
    '-e',
    'setTimeout(() => {}, 50)',
  );
  expect(first.timeoutMs).toBe(5000);
  await fs.writeFile(configPath, initialConfig + '  check_timeout_ms: 1\n');
  const rerun = await cli('check', 'rerun', 'demo', 'build');
  expect(rerun.timeoutMs).toBe(5000);
});

import { describe, expect, it } from 'vitest';

import {
  createNativeRunnerChannel,
  NATIVE_SKILL_COORDINATION,
} from '../../../domains/comet-native/native-runner-protocol.js';
import {
  validateNativeTrustedVerifierEnvelope,
  type NativeVerifierBinding,
} from '../../../domains/comet-native/native-verifier-protocol.js';

const binding: NativeVerifierBinding = {
  candidateId: 'candidate-1',
  identityProvider: NATIVE_SKILL_COORDINATION,
  builderExecutionRef: 'builder-1',
  iteration: 1,
  attempt: 1,
  acceptanceIds: ['A1', 'A2'],
  requiredChecksPassed: true,
};

const scopedBinding = {
  ...binding,
  acceptanceIds: ['A2'],
  knownAcceptanceIds: ['A1', 'A2'],
  previouslyPassedAcceptanceIds: ['A1'],
} as NativeVerifierBinding & {
  knownAcceptanceIds: readonly string[];
  previouslyPassedAcceptanceIds: readonly string[];
};

function finalResult(
  acceptance = [
    { id: 'A1', result: 'passed', reason: 'Observed the expected first behavior.' },
    { id: 'A2', result: 'passed', reason: 'Observed the expected second behavior.' },
  ],
) {
  return {
    kind: 'final-result',
    result: {
      iteration: 1,
      attempt: 1,
      verdict: 'pass',
      acceptance,
      risks: [],
      summary: 'All acceptance criteria passed.',
    },
  };
}

describe('Native package-local Verifier protocol', () => {
  it('accepts one complete Skill-coordinated result from a different execution', () => {
    const runner = createNativeRunnerChannel();
    const identity = runner.captureExecutionIdentity({
      identityProvider: 'codex-host',
      executionRef: 'verifier-1',
    });
    const envelope = runner.envelopeVerifierResponse({
      candidateId: 'candidate-1',
      identity,
      payload: finalResult(),
    });

    expect(validateNativeTrustedVerifierEnvelope({ envelope, binding })).toMatchObject({
      kind: 'final-result',
      result: { verdict: 'pass' },
    });
  });

  it('filters a known already-passed superset from a scoped final result', () => {
    const runner = createNativeRunnerChannel();
    const envelope = runner.envelopeVerifierResponse({
      candidateId: 'candidate-1',
      identity: runner.captureExecutionIdentity({
        identityProvider: 'codex-host',
        executionRef: 'verifier-scoped-superset',
      }),
      payload: finalResult(),
    });

    expect(
      validateNativeTrustedVerifierEnvelope({ envelope, binding: scopedBinding }),
    ).toMatchObject({
      kind: 'final-result',
      result: { acceptance: [{ id: 'A2', result: 'passed' }] },
    });
  });

  it('keeps nonexistent IDs unknown while distinguishing conflicting out-of-scope results', () => {
    const runner = createNativeRunnerChannel();
    const resultWith = (acceptance: ReturnType<typeof finalResult>['result']['acceptance']) =>
      runner.envelopeVerifierResponse({
        candidateId: 'candidate-1',
        identity: runner.captureExecutionIdentity({
          identityProvider: 'codex-host',
          executionRef: `verifier-${acceptance.at(-1)?.id}`,
        }),
        payload: finalResult(acceptance),
      });

    expect(() =>
      validateNativeTrustedVerifierEnvelope({
        envelope: resultWith([
          { id: 'A2', result: 'passed', reason: 'Scoped behavior passed.' },
          { id: 'A99', result: 'passed', reason: 'This criterion does not exist.' },
        ]),
        binding: scopedBinding,
      }),
    ).toThrow('unknown: A99');

    expect(() =>
      validateNativeTrustedVerifierEnvelope({
        envelope: resultWith([
          { id: 'A1', result: 'failed', reason: 'Previously passed behavior regressed.' },
          { id: 'A2', result: 'passed', reason: 'Scoped behavior passed.' },
        ]),
        binding: scopedBinding,
      }),
    ).toThrow('out-of-scope: A1=failed');
  });

  it('rejects an Agent-shaped plain object even if it forges identity fields', () => {
    expect(() =>
      validateNativeTrustedVerifierEnvelope({
        envelope: {
          candidateId: 'candidate-1',
          identityProvider: 'codex-host',
          verifierExecutionRef: 'verifier-1',
          payload: finalResult(),
        },
        binding,
      }),
    ).toThrow('trusted Runner');
  });

  it('does not trust a caller-provided host identity provider', () => {
    const runner = createNativeRunnerChannel();
    const identity = runner.captureExecutionIdentity({
      identityProvider: 'caller-claimed-host',
      executionRef: 'verifier-1',
    });

    expect(identity.identityProvider).toBe(NATIVE_SKILL_COORDINATION);
  });

  it('rejects same-execution self verification', () => {
    const runner = createNativeRunnerChannel();
    const envelope = runner.envelopeVerifierResponse({
      candidateId: 'candidate-1',
      identity: runner.captureExecutionIdentity({
        identityProvider: 'caller-claimed-host',
        executionRef: 'builder-1',
      }),
      payload: finalResult(),
    });
    expect(() => validateNativeTrustedVerifierEnvelope({ envelope, binding })).toThrow(
      'different executions',
    );
  });

  it.each([
    [[{ id: 'A1', result: 'passed', reason: 'ok' }], 'missing'],
    [
      [
        { id: 'A1', result: 'passed', reason: 'ok' },
        { id: 'A1', result: 'passed', reason: 'again' },
      ],
      'duplicate',
    ],
    [
      [
        { id: 'A1', result: 'passed', reason: 'ok' },
        { id: 'A3', result: 'passed', reason: 'unknown' },
      ],
      'unknown',
    ],
  ])('rejects incomplete acceptance coverage (%s)', (acceptance, message) => {
    const runner = createNativeRunnerChannel();
    const envelope = runner.envelopeVerifierResponse({
      candidateId: 'candidate-1',
      identity: runner.captureExecutionIdentity({
        identityProvider: 'codex-host',
        executionRef: 'verifier-1',
      }),
      payload: finalResult(acceptance),
    });
    expect(() => validateNativeTrustedVerifierEnvelope({ envelope, binding })).toThrow(message);
  });

  it('rejects pass when a required check failed or any criterion did not pass', () => {
    const runner = createNativeRunnerChannel();
    const envelope = runner.envelopeVerifierResponse({
      candidateId: 'candidate-1',
      identity: runner.captureExecutionIdentity({
        identityProvider: 'codex-host',
        executionRef: 'verifier-1',
      }),
      payload: finalResult([
        { id: 'A1', result: 'passed', reason: 'ok' },
        { id: 'A2', result: 'failed', reason: 'missing behavior' },
      ]),
    });
    expect(() => validateNativeTrustedVerifierEnvelope({ envelope, binding })).toThrow(
      'every acceptance',
    );
    expect(() =>
      validateNativeTrustedVerifierEnvelope({
        envelope: runner.envelopeVerifierResponse({
          candidateId: 'candidate-1',
          identity: runner.captureExecutionIdentity({
            identityProvider: 'codex-host',
            executionRef: 'verifier-2',
          }),
          payload: finalResult(),
        }),
        binding: { ...binding, requiredChecksPassed: false },
      }),
    ).toThrow('required check');
  });
});
